rule "Clean MikroTik Technical Fields"
when
    to_string($message.source) == "10.99.99.1"
then
    remove_field("facility");
    remove_field("facility_num");
    remove_field("level");
end

rule "Parse MikroTik Account Events"
when
    contains(to_string($message.message), "ACCOUNT:") &&
    contains(to_string($message.message), "user ") &&
    (contains(to_string($message.message), " logged in ") || contains(to_string($message.message), " logged out "))
then
    let m = grok(
        pattern: ".*user %{NOTSPACE:username} logged %{WORD:event_action} from %{NOTSPACE:client_address} via %{WORD:login_method}.*",
        value: to_string($message.message),
        only_named_captures: true
    );
    set_fields(m);
    set_field("event_category", "authentication");
end

rule "Parse MikroTik Common Fields"
when
    contains(to_string($message.message), "firewall,")
then
    let m = grok(
        pattern: ".*?%{WORD:firewall_chain}: in:%{NOTSPACE:interface_in} out:%{NOTSPACE:interface_out}, connection-state:%{WORD:connection_state} src-mac %{MAC:src_mac}, proto %{WORD:protocol}(?: \\(%{DATA:protocol_detail}\\))?,.* len %{INT:packet_length}",
        value: to_string($message.message),
        only_named_captures: true
    );
    set_fields(m);
    set_field("router_ip", to_string($message.source));
end

rule "Parse MikroTik Configuration Changes"
when
    contains(to_string($message.message), "CONFIG:") &&
    contains(to_string($message.message), "changed by")
then
    let m = grok(
        pattern: ".*CONFIG: : %{DATA:config_item} changed by %{DATA:access_source}\\(%{WORD:login_method}\\):%{NOTSPACE:username}@%{DATA:client_address}(?:/terminal(?:/action:%{INT:terminal_action})?)? \\(%{DATA:config_command}\\)$",
        value: to_string($message.message),
        only_named_captures: true
    );
    set_fields(m);
    set_field("event_category", "configuration");
    set_field("event_action", "changed");
    set_field("config_component", to_string(m["config_item"]));
    let raw_action = regex_replace(".*disabled=(yes|no).*", to_string(m["config_command"]), "$1", false);
    let action1 = regex_replace("^yes$", raw_action, "disabled", false);
    let action2 = regex_replace("^no$", action1, "enabled", false);
    set_field("config_action", action2);
end

rule "Parse MikroTik DNS Events"
when
    contains(to_string($message.message), "DNS:") &&
    contains(to_string($message.message), "dns,packet")
then
    let d = grok(
        pattern: ".*DNS: : <(?<dns_query>[^.:]+(?:\\.[^.:]+)*)\\.:%{WORD:dns_type}:.*",
        value: to_string($message.message),
        only_named_captures: true
    );
    set_fields(d);
    set_field("event_category", "dns");
end

rule "Parse MikroTik Firewall Action Common Fields"
when
    contains(to_string($message.message), "FW-ALLOW:") ||
    contains(to_string($message.message), "FW-DROP:") ||
    contains(to_string($message.message), "FW-REJECT:")
then
    let m = grok(
        pattern: ".*?%{WORD:firewall_chain}: in:%{NOTSPACE:interface_in} out:\\(unknown 0\\), connection-state:%{WORD:connection_state} src-mac %{MAC:src_mac}, proto %{WORD:protocol}(?: \\(%{DATA:protocol_detail}\\))?,.* len %{INT:packet_length}",
        value: to_string($message.message),
        only_named_captures: true
    );
    set_fields(m);
    set_field("interface_out", "router");
end

rule "Parse MikroTik Firewall Traffic"
when
    contains(to_string($message.message), "firewall,")
then
    let m = grok(
        pattern: "%{IP:src_ip}:%{INT:src_port}->%{IP:dst_ip}:%{INT:dst_port}",
        value: to_string($message.message),
        only_named_captures: true
    );

    set_fields(m);
end

rule "Parse MikroTik ICMP Traffic"
when
    contains(to_string($message.message), "firewall,") && contains(to_string($message.message), "proto ICMP")
then
    let m = grok(
        pattern: "%{IP:src_ip}->%{IP:dst_ip}",
        value: to_string($message.message),
        only_named_captures: true
    );
    set_fields(m);
end

rule "Parse MikroTik Input Common Fields"
when
    contains(to_string($message.message), "fw-input:")
then
    let m = grok(
        pattern: ".*?%{WORD:firewall_chain}: in:%{NOTSPACE:interface_in} out:\\(unknown 0\\), connection-state:%{WORD:connection_state} src-mac %{MAC:src_mac}, proto %{WORD:protocol}(?: \\(%{DATA:protocol_detail}\\))?,.* len %{INT:packet_length}",
        value: to_string($message.message),
        only_named_captures: true
    );
    set_fields(m);
    set_field("interface_out", "router");
end

rule "Parse MikroTik Interface Down"
when
    contains(to_string($message.message), "INTERFACE:") &&
    contains(to_string($message.message), "link down")
then
    let m = grok(
        pattern: ".*INTERFACE: : %{NOTSPACE:interface_name} link down.*",
        value: to_string($message.message),
        only_named_captures: true
    );
    set_fields(m);
    set_field("event_category", "interface");
    set_field("event_action", "down");
    set_field("event_severity", "critical");
    set_field("link_speed", "-");
    set_field("duplex", "-");
end

rule "Parse MikroTik Interface Up"
when
    contains(to_string($message.message), "INTERFACE:") &&
    contains(to_string($message.message), "link up")
then
    let m = grok(
        pattern: ".*INTERFACE: : %{NOTSPACE:interface_name} link up(?: \\(speed %{NOTSPACE:link_speed}, %{WORD:duplex} duplex\\))?.*",
        value: to_string($message.message),
        only_named_captures: true
    );
    set_fields(m);
    set_field("event_category", "interface");
    set_field("event_action", "up");
    set_field("event_severity", "normal");
end

rule "Parse MikroTik NAT Common Fields"
when
    contains(to_string($message.message), "firewall,") &&
    (contains(to_string($message.message), ",snat") || contains(to_string($message.message), ",dnat"))
then
    let m = grok(
        pattern: ".*?%{WORD:firewall_chain}: in:%{NOTSPACE:interface_in} out:%{NOTSPACE:interface_out}, connection-state:%{WORD:connection_state},%{WORD:nat_type} src-mac %{MAC:src_mac}, proto %{WORD:protocol}(?: \\(%{DATA:protocol_detail}\\))?,.* len %{INT:packet_length}",
        value: to_string($message.message),
        only_named_captures: true
    );
    set_fields(m);
end

rule "Parse MikroTik NAT Traffic"
when
    contains(to_string($message.message), ",snat") || contains(to_string($message.message), ",dnat")
then
    let n = grok(
        pattern: ".*connection-state:%{WORD:connection_state},%{WORD:nat_type}.*NAT %{IP:nat_original_src}->\\(%{IP:nat_translated_src}->%{IP:nat_destination}\\).*",
        value: to_string($message.message),
        only_named_captures: true
    );
    set_fields(n);
end

rule "Parse MikroTik Output Common Fields"
when
    contains(to_string($message.message), "fw-output:")
then
    let m = grok(
        pattern: ".*?%{WORD:firewall_chain}: in:\\(unknown 0\\) out:%{NOTSPACE:interface_out}, connection-state:%{WORD:connection_state} proto %{WORD:protocol}(?: \\(%{DATA:protocol_detail}\\))?,.* len %{INT:packet_length}",
        value: to_string($message.message),
        only_named_captures: true
    );
    set_fields(m);
    set_field("interface_in", "router");
end

rule "Parse MikroTik VPN Down"
when
    contains(to_string($message.message), "IPSEC:") &&
    contains(to_string($message.message), "killing ike2 SA:")
then
    let m = grok(
        pattern: ".*killing ike2 SA: %{NOTSPACE:vpn_peer_name} %{IP:vpn_ip_1}-%{IP:vpn_ip_2}.*",
        value: to_string($message.message),
        only_named_captures: true
    );
    set_fields(m);
    set_field("event_category", "vpn");
    set_field("event_action", "sa_terminated");
    set_field("event_severity", "info");
end

rule "Parse MikroTik VPN Up"
when
    contains(to_string($message.message), "IPSEC:") &&
    contains(to_string($message.message), "peer authorized:")
then
    let m = grok(
        pattern: ".*peer authorized: %{NOTSPACE:vpn_peer_name} %{IP:vpn_ip_1}-%{IP:vpn_ip_2}.*",
        value: to_string($message.message),
        only_named_captures: true
    );
    set_fields(m);
    set_field("event_category", "vpn");
    set_field("event_action", "up");
    set_field("event_severity", "normal");
end
